  ReligiousHoliday(month: 7, day: 21, name: '甘露节', religion: '锡克教', desc: '锡克教庆祝胡里节后一天的武士节日。', detail: '甘露节展示锡克教武士的军事传统和勇武精神。信徒举行武术表演、骑术比赛、诗歌朗诵和集体祈祷。', yi: '武术表演、祈祷、免费供餐', ji: '禁止饮酒吸烟'),
  ReligiousHoliday(month: 7, day: 24, name: '先驱者日', religion: '摩门教', desc: '纪念杨百翰率首批先驱进入盐湖谷。', detail: '先驱者日为犹他州年度最大庆典，包含游行、牛仔竞技及复古活动。', yi: '参加庆典、游行、历史纪念', ji: '摩门教信徒周日避免购物娱乐'),
  ReligiousHoliday(month: 8, day: 6, name: '显荣节', religion: '东正教', desc: '纪念耶稣在大博尔山显圣容。', detail: '显荣节纪念耶稣在大博尔山在门徒面前显出神圣光辉。东正教在这天祝福水果。', yi: '参加礼拜、祝福水果、祈祷', ji: '斋期内遵守斋规'),
  ReligiousHoliday(month: 8, day: 15, name: '圣母升天节', religion: '天主教', desc: '纪念圣母玛利亚灵魂与肉身一同升天的节日。', detail: '圣母升天节是天主教和东正教的重要节日。在法国、意大利、西班牙等许多天主教国家是公共假日。教堂举行隆重弥撒。', yi: '参加弥撒、手持鲜花蜡烛游行', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 8, day: 19, name: '盂兰盆节', religion: '佛教', desc: '佛教重要节日，又称中元节，祭祀祖先。', detail: '盂兰盆节源于目连救母故事。中国"中元节"、日本"お盆"、韩国"百中节"都源于此。日本盂兰盆舞和放河灯是著名节庆活动。', yi: '诵经、供僧、祭祖、放河灯', ji: '避免夜间外出（民间信仰）、杀生'),
  ReligiousHoliday(month: 8, day: 26, name: '克里希纳诞辰', religion: '印度教', desc: '纪念印度教神祇克里希纳诞辰的节日。', detail: '克里希纳诞辰纪念毗湿奴第八化身克里希纳的诞生。信徒守夜至午夜诵经，寺庙举行摇篮礼。', yi: '守夜、诵经、献供、禁食至午夜', ji: '午夜前不宜进食'),
  ReligiousHoliday(month: 8, day: 29, name: '巴哈欧拉升天日', religion: '巴哈伊教', desc: '纪念巴哈欧拉于1892年逝世。', detail: '巴哈欧拉升天日纪念巴哈欧拉逝世。信徒在清晨举行特别祈祷会。', yi: '清晨祈祷、诵读经文', ji: '此日为圣日，停止工作'),
  ReligiousHoliday(month: 9, day: 7, name: '象头神节', religion: '印度教', desc: '纪念象头神伽内什的节日。', detail: '象头神节是印度教最盛大的公众节日之一。节日持续1-11天，最后一天举行盛大的浸像仪式。', yi: '安放神像、献花供果、诵经、游行', ji: '不宜在此期间开始新事业（部分传统）'),
  ReligiousHoliday(month: 9, day: 9, name: '重阳节', religion: '道教', desc: '斗姆元君与真武大帝圣诞，也是登高敬老的日子。', detail: '重阳节在农历九月初九。道教视为斗姆元君与真武大帝圣诞。也是中国传统节日，登高赏秋，现为老年节。', yi: '登高、敬老、饮菊花酒、佩茱萸', ji: '避免说不敬老的话'),
  ReligiousHoliday(month: 9, day: 14, name: '十字架举荣节', religion: '东正教', desc: '纪念十字架被发现与高举。', detail: '十字架举荣节纪念海伦娜发现真十字架。东正教将十字架高举于会众中央，信徒敬礼叩拜。', yi: '参加礼拜、敬礼十字架', ji: '斋期内遵守斋规'),
  ReligiousHoliday(month: 9, day: 15, name: '赎罪日', religion: '犹太教', desc: '犹太教最神圣的日子，进行禁食和忏悔。', detail: '赎罪日是犹太教最神圣最庄严的日子。犹太人完全禁食25小时，在会堂中祈祷忏悔。以色列在这天全国停摆。', yi: '禁食、祈祷、忏悔、施舍', ji: '严禁饮食、洗浴、穿皮鞋、行房、工作'),
  ReligiousHoliday(month: 9, day: 20, name: '住棚节', religion: '犹太教', desc: '纪念以色列人在旷野住棚的七天节日。', detail: '住棚节持续七天。犹太人建造"苏卡"（临时棚屋），全家人在苏卡中吃饭，手持"四种植物"游行。', yi: '建造苏卡、在苏卡中用餐、手持四种植物游行', ji: '不可在苏卡外用餐（节日期间）'),
  ReligiousHoliday(month: 9, day: 26, name: '十胜节', religion: '印度教', desc: '纪念罗摩战胜魔王罗波那的节日。', detail: '十胜节纪念罗摩击败魔王罗波那，象征正义战胜邪恶。焚烧巨大魔王像，象征恶的毁灭。', yi: '焚烧魔王像、启动新事业、祈祷', ji: '避免不敬神灵'),
  ReligiousHoliday(month: 9, day: 29, name: '米迦勒节', religion: '基督教', desc: '纪念天使长米迦勒和众天使的节日。', detail: '米迦勒节纪念天使长米迦勒和众天使。英国传统上在这天吃鹅肉。许多大学和法律年度从米迦勒节开始。', yi: '参加礼拜、感恩、团聚', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 10, day: 3, name: '中秋节', religion: '传统', desc: '中国传统节日，家人团聚赏月吃月饼。', detail: '中秋节是中国仅次于春节的第二大传统节日，有2000多年历史。以月圆象征团圆，家人围坐赏月、吃月饼。2006年列入非遗名录。', yi: '赏月、团聚、吃月饼、祭月', ji: '忌对月不敬、忌独自赏月（民间说法）'),
  ReligiousHoliday(month: 10, day: 3, name: '开天节', religion: '天道教', desc: '纪念檀君开国，天道教与民族主义传统紧密相连。', detail: '开天节纪念檀君建立古朝鲜。韩国在10月3日举行纪念活动。', yi: '参加纪念仪式、祈祷', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 10, day: 12, name: '排灯节', religion: '印度教', desc: '印度教光明节，象征光明战胜黑暗。', detail: '排灯节是印度教最盛大的节日。核心仪式是点燃油灯和蜡烛，象征光明驱散黑暗。人们打扫房屋、穿新衣、放鞭炮、交换甜食。', yi: '点灯、穿新衣、分享甜食、拜访亲友', ji: '避免在黑暗中不点灯'),
  ReligiousHoliday(month: 10, day: 20, name: '古鲁那纳克诞辰', religion: '锡克教', desc: '纪念锡克教创始人古鲁那纳克的诞辰。', detail: '古鲁那纳克诞辰纪念锡克教创始人诞生。节日持续48小时不间断诵读经典，当天凌晨举行晨祷，之后免费提供圣餐。', yi: '不间断诵读经典、晨祷、免费供餐、游行', ji: '禁止饮酒吸烟'),
  ReligiousHoliday(month: 10, day: 31, name: '万圣节', religion: '基督教', desc: '诸圣节前夕，纪念所有圣徒的节日。', detail: '万圣节是诸圣节的前夜，起源于凯尔特人的萨温节。"Trick or Treat"习俗始于美国。如今万圣节已成为全球性娱乐节日。', yi: '纪念先人、参加教会活动', ji: '避免过度恐惧或不当装扮'),
  ReligiousHoliday(month: 11, day: 1, name: '诸圣节', religion: '基督教', desc: '纪念所有圣徒和殉道者的节日。', detail: '诸圣节纪念所有已封圣的圣徒和殉道者。在天主教国家11月1日是公共假日，人们去墓地为已故亲人献花点蜡烛。', yi: '参加弥撒、为亡者祈祷、扫墓献花', ji: '不宜庆祝宴乐'),
  ReligiousHoliday(month: 11, day: 2, name: '万灵节', religion: '基督教', desc: '纪念所有亡者的节日。', detail: '万灵节是天主教纪念所有已亡信众的节日。信徒为亡者祈祷、献弥撒、扫墓点烛。墨西哥将此日合并为"亡灵节"。', yi: '为亡者祈祷、点烛、扫墓', ji: '不宜庆祝宴乐'),
  ReligiousHoliday(month: 11, day: 12, name: '光明节', religion: '犹太教', desc: '纪念马加比起义胜利和圣殿灯油奇迹的八天节日。', detail: '光明节持续八天，纪念马加比起义收复圣殿的奇迹。核心仪式是点燃九灯台：每晚增加一盏灯。家庭习俗包括玩陀螺、吃油炸食品、赠送礼物。', yi: '点灯、祈祷、吃油炸食品、玩陀螺、赠礼', ji: '光明节期间灯台不可熄灭'),
  ReligiousHoliday(month: 11, day: 15, name: '佛成道日', religion: '佛教', desc: '纪念佛陀在菩提树下证悟成佛的日子。', detail: '佛成道日在农历十二月初八，纪念佛陀悟道成佛。中国寺庙在这天煮"腊八粥"供众，已融入民间成为"腊八节"。', yi: '煮腊八粥、诵经、供灯、禅修', ji: '避免杀生、荤食'),
  ReligiousHoliday(month: 11, day: 24, name: '锡克教殉道节', religion: '锡克教', desc: '纪念第九任古鲁得格·巴哈杜尔殉道。', detail: '锡克教殉道节纪念第九任古鲁为保护宗教自由而殉道。锡克教徒朝圣，举行祈祷和诵经。', yi: '朝圣、祈祷、诵经', ji: '禁止饮酒吸烟'),
  ReligiousHoliday(month: 11, day: 26, name: '圣约日', religion: '巴哈伊教', desc: '纪念阿博都巴哈被宣布为圣约的中心。', detail: '圣约日纪念阿博都巴哈被正式宣布为巴哈欧拉圣约的中心与诠释者。', yi: '祈祷、聚会、纪念', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 12, day: 8, name: '圣母无染原罪节', religion: '天主教', desc: '纪念圣母玛利亚受孕时未受原罪玷污的节日。', detail: '圣母无染原罪节在12月8日，是天主教信条。在许多天主教国家是公共假日，也是圣诞季正式开始的日子。', yi: '参加弥撒、开始圣诞装饰', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 12, day: 12, name: '瓜达卢佩圣母节', religion: '天主教', desc: '纪念瓜达卢佩圣母显现的节日。', detail: '瓜达卢佩圣母节纪念1531年圣母在墨西哥显现。数百万墨西哥人前往朝圣。瓜达卢佩圣母是墨西哥和全美洲的主保圣人。', yi: '朝圣、祈祷、唱颂歌', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 12, day: 21, name: '冬至', religion: '传统', desc: '北半球白昼最短的一天，中国有"冬至大如年"之说。', detail: '冬至中国自古重视，有"冬至大如年"的说法。北方吃饺子、南方吃汤圆。古代是天子祭天的大日子。', yi: '祭祖、吃饺子/汤圆、团圆', ji: '民间忌冬至不出门、忌晚归'),
  ReligiousHoliday(month: 12, day: 21, name: '密特拉节', religion: '琐罗亚斯德教', desc: '纪念光明战胜黑暗的转折点。', detail: '密特拉节在冬至，纪念光明战胜黑暗的转折点，波斯古密特拉信仰的遗存。', yi: '点燃圣火、祈祷、庆祝光明重生', ji: '禁止熄灭圣火'),
  ReligiousHoliday(month: 12, day: 23, name: '约瑟·斯密诞辰', religion: '摩门教', desc: '纪念摩门教创始人约瑟·斯密诞辰。', detail: '纪念摩门教创始人约瑟·斯密诞辰。各分会举办历史讲座及灵修会。', yi: '参加灵修会、历史讲座', ji: '摩门教信徒禁止饮酒咖啡'),
  ReligiousHoliday(month: 12, day: 25, name: '圣诞节', religion: '基督教', desc: '纪念耶稣基督诞生的重要节日。', detail: '圣诞节是基督教最广为人知的节日，纪念耶稣诞生。习俗包括圣诞树、圣诞老人、唱颂歌、交换礼物等。', yi: '参加圣诞礼拜、家庭团聚、交换礼物、唱颂歌', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 12, day: 26, name: '节礼日', religion: '基督教', desc: '圣诞节后的第一天，传统上向穷人施舍礼物。', detail: '节礼日传统上向穷人施舍礼物。英联邦国家定为公共假日。如今已成为全球最大购物折扣日之一。', yi: '施舍、赠礼、购物', ji: '无特殊禁忌'),
  ReligiousHoliday(month: 12, day: 31, name: '法瓦蒂干节', religion: '琐罗亚斯德教', desc: '纪念亡魂回归探访生者。', detail: '法瓦蒂干节在12月31日至1月4日，纪念亡魂回归。信徒在火庙祈祷，施舍食物。', yi: '祈祷、施舍、纪念亡者', ji: '禁止在火前谈论污秽之事'),
];
